<?php
namespace App\Http\Controllers\Backend;
use App\Http\Controllers\Controller;use App\Models\Setting;use App\Services\PdfService;use App\Services\ReportService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Http\Response;use Illuminate\Support\Facades\Gate;use Illuminate\View\View;use Yajra\DataTables\Facades\DataTables;
class ReportController extends Controller{public function __construct(private readonly ReportService $reports){}public function index(Request $r,string $report):View|JsonResponse{$title=$this->title($report);Gate::authorize('reports.view');if($r->ajax())return DataTables::of($this->reports->query($report,$r))->addIndexColumn()->editColumn('description',fn($x)=>str($x->description)->replace('_',' ')->title())->editColumn('amount',fn($x)=>number_format((float)$x->amount,2))->toJson();return view('backend.reports.index',compact('report','title'));}public function pdf(Request $r,string $report,PdfService $pdf):Response{$title=$this->title($report);Gate::authorize('reports.export');$records=$this->reports->query($report,$r)->orderByDesc('report_date')->get();$s=Setting::values();return $pdf->reportDownload('pdf.modules.generic-report',['records'=>$records,'title'=>$title,'company'=>['name'=>$s['company_name']??'Cholavin','address'=>$s['company_address']??''],'generatedAt'=>now()],$report.'-'.now()->format('Ymd-His').'.pdf',$title,'L');}private function title(string $r):string{abort_unless(isset(ReportService::REPORTS[$r]),404);return ReportService::REPORTS[$r];}}
